    StockMovement(
      id: (json['id'] as num?)?.toInt() ?? Isar.autoIncrement,
      productId: (json['productId'] as num?)?.toInt() ?? 0,
      productName: json['productName'] as String? ?? '',
      type:
          $enumDecodeNullable(_$StockMovementTypeEnumMap, json['type']) ??
          StockMovementType.adjustment,
      qty: (json['qty'] as num?)?.toInt() ?? 0,
      reason: json['reason'] as String? ?? '',
      supplierId: (json['supplierId'] as num?)?.toInt() ?? 0,
      createdAt: json['createdAt'] == null
          ? null
          : DateTime.parse(json['createdAt'] as String),
    );

Map<String, dynamic> _$StockMovementToJson(StockMovement instance) =>
    <String, dynamic>{
      'id': instance.id,
      'productId': instance.productId,
      'productName': instance.productName,
      'type': _$StockMovementTypeEnumMap[instance.type]!,
      'qty': instance.qty,
      'reason': instance.reason,
      'supplierId': instance.supplierId,
